import assert from 'node:assert/strict';
import { Grid } from './runtime/sources/common/src/grid/grid';
import { getPositionForCells } from './runtime/sources/common/src/grid/grid_math';
import { traceGridRayCells } from './runtime/sources/common/src/grid/ray_traversal';
import { scatteredMountainsForSeed } from './runtime/sources/common/src/grid/scattered_mountains';
import { creatureInfo, creatureIdForName } from './runtime/sources/common/src/ai/setup/creature_score';
import { PBTypes } from './runtime/sources/common/src/generated/protobuf/v1/types';
export const POLICY='public-terrain-formation-reflection-v1';
const key=(p:any)=>(p.x<<4)|p.y;
export function terrainFormation(session:any,team:number,units:any[],positions:any[]) {
  const bodies=units.map(u=>[u.getName(),u.getAmountAlive(),u.getFootprintWidth(),u.getFootprintHeight()]);
  const result={bodies,positions:positions.map(p=>({...p})),diagnostic:{policy:POLICY,changed:false,baselineCost:0,reflectedCost:0}};
  // The first screen isolates the actual randomly placed neutral barrels. Lava's fixed symmetric
  // geometry offers no gain from reflection; its map feature must not be described as wholly blind.
  if(session.grid.getGridType()!==PBTypes.GridVals.BLOCK_CENTER) return result;
  const settings=session.grid.getSettings();
  const grid=new Grid(settings,PBTypes.GridVals.BLOCK_CENTER);
  const neutral=scatteredMountainsForSeed(session.gameId).map(x=>x.cell);
  grid.setScatteredMountains(neutral);
  const blocked=new Set(neutral.map(key));
  const matrix=grid.getMatrixNoUnits();
  const legal=session.allowedPlacementHashesByTeam.get(team) as Set<number>;
  const cells=(i:number,p:any)=>Array.from({length:bodies[i][2]*bodies[i][3]},(_,j)=>({x:p.x-j%bodies[i][2],y:p.y-Math.floor(j/bodies[i][2])}));
  const reflected=positions.map((p,i)=>({x:p.x,y:15-p.y+bodies[i][3]-1}));
  if(reflected.some((p,i)=>cells(i,p).some(c=>!legal.has(key(c))||blocked.has(key(c))))) return result;
  const occupied=new Set<number>();
  for(let i=0;i<reflected.length;i++)for(const c of cells(i,reflected[i])){assert(!occupied.has(key(c)));occupied.add(key(c));}
  const score=(ps:any[])=>{
    let cost=0;
    for(let i=0;i<units.length;i++) {
      const u=units[i],p=ps[i],id=creatureIdForName(u.getName());assert(id!==undefined);
      const info=creatureInfo(id)!;const weight=u.getAmountAlive()*info.exp/1000;
      if(u.getAttackType()===PBTypes.AttackVals.RANGE) {
        const origin=getPositionForCells(settings,cells(i,p))!;
        let blockedRays=0;
        for(let y=1;y<=14;y++) {
          const target=getPositionForCells(settings,[{x:team===2?12:3,y}])!;
          if(traceGridRayCells(settings,origin,target).some(([c])=>blocked.has(key(c))))blockedRays++;
        }
        cost+=weight*blockedRays/14;
      } else if(!u.canFly() && !info.nativeSpellbook && [PBTypes.AttackVals.MELEE,PBTypes.AttackVals.MELEE_MAGIC].includes(u.getAttackType())) {
        const targetX=team===2?9+u.getFootprintWidth():5;
        const routes=session.pathHelper.getMovePath(p,matrix,32,undefined,false,u.isSmallSize(),u.canTraverseLava(),u.hasAbilityActive('In Its Own World'),u.getFootprintWidth(),u.getFootprintHeight()).knownPaths;
        let shortest=Infinity;
        for(const alternatives of routes.values())for(const r of alternatives)if(r.cell.x===targetX)shortest=Math.min(shortest,r.weight);
        const detour=Number.isFinite(shortest)?Math.max(0,shortest-Math.abs(targetX-p.x)):16;
        cost+=weight*detour/4;
      }
    }
    return cost;
  };
  result.diagnostic.baselineCost=score(positions);result.diagnostic.reflectedCost=score(reflected);
  if(result.diagnostic.reflectedCost<result.diagnostic.baselineCost-1e-9){result.positions=reflected;result.diagnostic.changed=true;}
  return result;
}
